194	 * Resolve a host string to its first corresponding network address.
195	 *
196	 * @see LookupHost(const std::string&, std::vector<CNetAddr>&, unsigned int, bool) for
197	 *      additional parameter descriptions.
198	 */
199	bool LookupHost(const std::string& name, CNetAddr& addr, bool fAllowLookup)
200	{
201	    if (!ValidAsCString(name)) {
202	        return false;
203	    }
204	    std::vector<CNetAddr> vIP;
205	    LookupHost(name, vIP, 1, fAllowLookup);
206	    if(vIP.empty())
207	        return false;
208	    addr = vIP.front();
209	    return true;
210	}
