40	template <typename... Callables>
41	void CallOneOf(FuzzedDataProvider& fuzzed_data_provider, Callables... callables)
42	{
43	    constexpr size_t call_size{sizeof...(callables)};
44	    static_assert(call_size >= 1);
45	    const size_t call_index{fuzzed_data_provider.ConsumeIntegralInRange<size_t>(0, call_size - 1)};
46	
47	    size_t i{0};
48	    return ((i++ == call_index ? callables() : void()), ...);
49	}
