162	[[nodiscard]] inline CTxMemPoolEntry ConsumeTxMemPoolEntry(FuzzedDataProvider& fuzzed_data_provider, const CTransaction& tx) noexcept
163	{
164	    // Avoid:
165	    // policy/feerate.cpp:28:34: runtime error: signed integer overflow: 34873208148477500 * 1000 cannot be represented in type 'long'
166	    //
167	    // Reproduce using CFeeRate(348732081484775, 10).GetFeePerK()
168	    const CAmount fee = std::min<CAmount>(ConsumeMoney(fuzzed_data_provider), std::numeric_limits<CAmount>::max() / static_cast<CAmount>(100000));
169	    assert(MoneyRange(fee));
170	    const int64_t time = fuzzed_data_provider.ConsumeIntegral<int64_t>();
171	    const unsigned int entry_height = fuzzed_data_provider.ConsumeIntegral<unsigned int>();
172	    const bool spends_coinbase = fuzzed_data_provider.ConsumeBool();
173	    const unsigned int sig_op_cost = fuzzed_data_provider.ConsumeIntegralInRange<unsigned int>(0, MAX_BLOCK_SIGOPS_COST);
174	    return CTxMemPoolEntry{MakeTransactionRef(tx), fee, time, entry_height, spends_coinbase, sig_op_cost, {}};
175	}
