/**
 * A mocked Sock for use in fuzz tests. Its `Send()`, `Recv()` and `Wait()`
 * return values and behavior are controlled by the provided
 * `FuzzedDataProvider` so that the code that uses the socket can be exercised
 * against arbitrary (adversarial) I/O responses without touching a real
 * network socket.
 */
class FuzzedSock : public Sock
{
    FuzzedDataProvider& m_fuzzed_data_provider;

public:
    explicit FuzzedSock(FuzzedDataProvider& fuzzed_data_provider);

    ~FuzzedSock() override;

    FuzzedSock& operator=(Sock&& other) override;

    SOCKET Get() const override;

    SOCKET Release() override;

    void Reset() override;

    ssize_t Send(const void* data, size_t len, int flags) const override;

    ssize_t Recv(void* buf, size_t len, int flags) const override;

    bool Wait(std::chrono::milliseconds timeout, Event requested, Event* occurred = nullptr) const override;
};

[[nodiscard]] inline FuzzedSock ConsumeSock(FuzzedDataProvider& fuzzed_data_provider)
{
    return FuzzedSock{fuzzed_data_provider};
